      "card_ids": ["C20"],
      "claim": "Benzothiazole analogue 44 showed good CNS penetration with a 5-fold brain:plasma exposure ratio in in vivo PK studies, directly supporting meaningful CNS access after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Semagacestat CSF concentrations in humans indicated good CNS penetration, providing direct human evidence for meaningful CNS access.",
      "evidence_role": "supportive"
